// textile-studio/names.js - translated names of pieces (with the derived ones: linings, interfacings, pockets, jets,
// flaps, bags, neck facings), materials, garments, details and their variants.
//
// Design: piece ids are generated by the drafting code (garment/*) by suffixing a base id ('frontLining',
// 'pocket-<x>-<pos>-<type>-flap'), so a dictionary entry per derived id would explode combinatorially. Instead the
// name is COMPOSED from the base piece name and the material / part name, recursively (a lining of an interfacing
// still reads correctly). Called at render time, never cached: a language switch re-renders and must re-translate.

import { ED_I18N, t } from '../ui/i18n.js';

// Optional-key probe: returns the translation only when the key exists in the English (reference) dictionary, else
// null so the caller can try a more generic key. t() alone cannot be used for this: it never fails, it humanizes.
const has = (k) => (k in ED_I18N.en ? t(k) : null);

export function pieceName(id) {
  // Order matters: suffix rules first (they recurse on the base id), then prefix families, then the plain lookup.
  // The regexes are anchored (^...$) so 'frontLiningPocket' is not misread as a lining.
  const s = String(id || '');
  let m;
  if ((m = /^(.*)Lining$/.exec(s))) return `${pieceName(m[1])} · ${t('mat.lining')}`;
  if ((m = /^(.*)Interfacing$/.exec(s))) return `${pieceName(m[1])} · ${t('mat.interfacing')}`;
  // NeckFacing ignores the base: one facing piece covers the whole neckline, the garment name would only add noise.
  if ((m = /^(.*)NeckFacing$/.exec(s))) return t('piece.neckFacing');
  if ((m = /^(.*)Wadding$/.exec(s))) return `${pieceName(m[1])} · ${t('mat.wadding')}`;
  if (/^layer-/.test(s)) return t('piece.layer');
  if (/^embroidery/.test(s)) return t('piece.embroidery');
  // pocket-<id>-<position>-<type>[-jet|jets|flap|bag]: the type picks the pocket name, the position the side, the
  // optional tail the sub-piece. [^-]+ for the id: ids never contain '-' (uid() is base36).
  if ((m = /^pocket-[^-]+-([a-z]+)-([a-zA-Z]+)(?:-(jet|jets|flap|bag))?$/.exec(s))) {
    const base = `${t('det.pocket.' + m[2])} (${t('pos.' + m[1])})`;
    return m[3] ? `${base} · ${t('piece.' + m[3])}` : base;
  }
  if (/^sideSeam-bag$/.test(s)) return `${t('det.pocket.sideSeam')} · ${t('piece.bag')}`;
  if (/^loop-/.test(s)) return t('piece.beltLoop');
  // has(...) || t(...): an unknown id still yields a readable humanized label instead of an empty string.
  return has('piece.' + s) || t('piece.' + s);
}

export const materialName = (m) => t('mat.' + m);
export const garmentName = (g) => t('g.' + g);
export const detailName = (type) => t('det.' + type);
// A detail-specific variant label ('det.lapel.peak') wins over the shared one ('var.peak'): the same variant word
// may need a different translation per detail.
export const variantName = (type, v) => has(`det.${type}.${v}`) || t('var.' + v);
